#pragma once

#include <ArduinoJson.h>

#include <string>

/**
 * Read-only configuration for Desk mode, loaded from /.crosspoint/desk.json on the SD card.
 *
 * Unlike the *Store singletons this is never written back by the firmware: the file is hand-edited
 * (or generated by the server that feeds the desk screen), so there is no toJson/saveToFile.
 * See docs/desk-mode.md for the file format.
 */
struct DeskConfig {
  static constexpr const char* PATH = "/.crosspoint/desk.json";
  static constexpr int DEFAULT_POLL_S = 60;
  static constexpr int MIN_POLL_S = 10;
  static constexpr int MAX_POLL_S = 3600;
  static constexpr int DEFAULT_FULL_REFRESH_EVERY = 20;

  std::string imageUrl;    // GET -> 1-bit BMP sized to the screen (required)
  std::string versionUrl;  // GET -> short text that changes when the image changes (optional)
  std::string webhookUrl;  // POST {"action":"<name>"} (required)
  int pollS = DEFAULT_POLL_S;
  int fullRefreshEvery = DEFAULT_FULL_REFRESH_EVERY;

  // Fills `out` from a parsed desk.json document. Returns false and sets `error` to a short reason
  // when a required field is missing or malformed.
  static bool fromJson(JsonVariantConst root, DeskConfig& out, std::string& error);

  // Reads PATH from the SD card. Returns false and fills `error` when the file is missing,
  // unreadable, or invalid.
  static bool load(DeskConfig& out, std::string& error);
};
